1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Scenario = {
16	  customer: { yearsWithMHPCO: number };
17	  steps: Step[];
18	};
19	
20	export type StepResult = {
21	  premium: number;
22	};
23	
24	export type ScenarioResults = {
25	  results: StepResult[];
26	};
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	};
35	
36	// 10 % of the base premium, expressed as a tenth so that integer bases stay
37	// exact: 100 * 1.1 is 110.00000000000001 in binary floating point.
38	const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10;
39	
40	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
41	
42	const withFirstInsuranceSurcharge = (base: number): number =>
43	  base + base / FIRST_INSURANCE_SURCHARGE_DIVISOR;
44	
45	const itemPremium = (item: Item): number =>
46	  withFirstInsuranceSurcharge(basePremium(item));
47	
48	// Amounts are rounded in the MHPCO's favor: premiums round up.
49	const roundPremium = (amount: number): number => Math.ceil(amount);
50	
51	const quote = (step: Step): StepResult => ({
52	  premium: roundPremium(
53	    step.items.reduce(
54	      (total, item) => total + itemPremium(item),
55	      PROCESSING_FEE,
56	    ),
57	  ),
58	});
59	
60	export const runScenario = (scenario: Scenario): ScenarioResults => ({
61	  results: scenario.steps.map(quote),
62	});
